import sys, json, datetime, time

# THE LEAD (GH #1447, D38 C1, R-38-4 Nr. 4; a hive of its own since GH #1474,
# R-58-9 Nr. 5). The switch of a composite that chooses between targets:
# which way a call leaves on, to which target, for what reason, what becomes
# of the turn's speculation, whether the quick voice gave the turn up,
# whether an errand is pending and which side calls go beside it, with which text. The curator's `./policy`
# asks once per call
# (`lead_ask`, beside its ledger reads, across the curator's rim and this
# hive's) and builds the window on the verdict (`lead_verdict`, home on the
# curator's `in_lead`); the lead's memory -- `escalated:`, `consult_pending:`,
# the speculation rows -- lives in its own store `./state`, never in the
# curator's ledger. `lead_verdict(stamp, head, state)` is a PURE function of
# its input: the table pin loads it via `ast`.
# wall-clock: perf_counter -- only the station's own handle_ms, never a decision.
T0 = time.perf_counter()
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}
ME = "lead"
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"


def unset(v):
    return v is None or (isinstance(v, str) and not v.strip())


def switch_on(v):
    """One switch (#1370): JSON true, "1", "true" or "on" is on."""
    return str(v).strip().lower() in ("1", "true", "on")


def knob_int(name, default):
    """A number knob: the param, else the literal beside it."""
    v = P.get(name)
    try:
        return default if unset(v) else int(str(v))
    except ValueError:
        return default


def _count(key, default):
    """A count knob (GH #943): null, empty, unparsable or below 1 is the default."""
    v = P.get(key)
    if unset(v):
        return default
    try:
        n = int(float(v))
    except (TypeError, ValueError):
        return default
    return n if n >= 1 else default


def names_list(v):
    """A list of names from a list or a comma string, blanks dropped."""
    if isinstance(v, str):
        v = v.split(",")
    return [str(x).strip() for x in (v if isinstance(v, list) else []) if str(x).strip()]


def family_in(name, names):
    """A tool name (`web_search`) or a family (`web`) among `names`."""
    return name in names or name.split("_")[0] in names


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def loads(text, default):
    try:
        v = json.loads(text)
    except Exception:
        return default
    return v if v is not None else default


def epoch_us(value):
    s = str(value or "").strip()
    try:
        t = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
    except ValueError:
        return None
    if t.tzinfo is None:
        t = t.replace(tzinfo=datetime.timezone.utc)
    delta = t - datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
    return (delta.days * 86400 + delta.seconds) * 1000000 + delta.microseconds


def stamp_after(stamp, ms):
    """A stored stamp `ms` milliseconds later, in the form `FMT`; empty for
    a stamp that does not parse (the mark then goes at the next call)."""
    us = epoch_us(stamp)
    if us is None:
        return ""
    return (datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            + datetime.timedelta(microseconds=us + ms * 1000)).strftime(FMT)


# >>> ways v1 (GH #1247, moved from curator/policy by GH #1447)
# D58 target (contract point 9, OR-d58-2.target.8, .36): the lead names
# targets, never ways. The route cell stamps every turn; `path_routes` maps a
# path to a TARGET (a name the composite wires) or to an errand CLASS (a name
# `departures` lists: the call leaves the composite, with its wait); `*`
# names the target of every turn whose path has none -- no path, an unknown
# one, the round that answers an errand. GH #1478: the lead names no class
# of its own; a class the composition's model stamps (a how-question, say)
# goes by `path_routes` like any other, and what such a turn gets in its
# window is `./policy`'s `class_notes`. `fallback` maps a
# target to the target its round goes to when it gives up (`target:target`);
# a target with a fallback is a fast one (it may hand its round on).
# Unset, the lead names no target at all.


def routes_of(v):
    """`name:value` pairs, comma separated (or a JSON object), as a map."""
    if isinstance(v, dict):
        return {str(k): str(w) for k, w in v.items()}
    pairs = [p.split(":", 1) for p in str(v or "").split(",") if ":" in p]
    return {k.strip(): w.strip() for k, w in pairs if k.strip()}


def departures_of(v):
    """`departures` as `{class: (wait_ms, pending_ms or None)}`: `class:wait`
    or `class:wait:pending` pairs, comma separated."""
    out = {}
    for p in str(v or "").split(","):
        f = [x.strip() for x in p.split(":")]
        if len(f) < 2 or not f[0]:
            continue
        try:
            out[f[0]] = (int(f[1]), int(f[2]) if len(f) > 2 and f[2] else None)
        except ValueError:
            sys.stderr.write("lead/lead: departure %r is not class:wait_ms -- dropped\n" % p)
    return out


PATH_ROUTES = routes_of(P.get("path_routes"))
DEFAULT_ROUTE = PATH_ROUTES.pop("*", "")
DEPARTURES = departures_of(P.get("departures"))
FALLBACK = routes_of(P.get("fallback"))
SPEC_TARGET = str(P.get("spec_target") or "").strip()
BRIDGE_TARGETS = routes_of(P.get("bridge_target"))
if not BRIDGE_TARGETS and str(P.get("bridge_target") or "").strip():
    BRIDGE_TARGETS = {"*": str(P.get("bridge_target")).strip()}
ERRAND_TOOL = str(P.get("errand_tool") or "").strip()
ERRAND_FAMILY = str(P.get("errand_family") or "").strip()
# GH #1435: "1" sends a turn of a fast target that needs the memory to its
# fallback.
MEMORY_TO_BRAIN = switch_on(P.get("memory_to_brain"))
QUICK_SPECULATIVE = switch_on(P.get("quick_speculative"))
SPEC_TOOLS = names_list(P.get("spec_tools") or "")
QUICK_MAX_ITER = knob_int("quick_max_iter", 2)
CONSULT_PENDING_MS = _count("consult_pending_ms", 120000)
# OR-d38-3.c1.44: how many turns of a session `spec_called:` remembers.
SPEC_CALLED_TURNS = _count("spec_called_turns", 16)
DELTA_SPEC = switch_on(P.get("delta_speculation"))
INTERRUPT_ON_DELTA = switch_on(P.get("interrupt_on_delta"))


def json_knob(name):
    """A knob that holds a JSON object, as its text or as the object itself;
    {} when unset, unparsable or no object (said on stderr)."""
    v = P.get(name)
    if unset(v):
        return {}
    if isinstance(v, str):
        try:
            v = json.loads(v)
        except ValueError:
            v = None
    if not isinstance(v, dict):
        sys.stderr.write("lead/lead: %s is no JSON object -- {}\n" % name)
        return {}
    return v


def wording_map(v):
    """`bridge_wording` as `{class: form}`: `<class>:<form>` pairs, comma
    separated; a form other than `soon` or `later` is dropped."""
    out = {}
    for part in str(v or "").split(","):
        name, _, form = part.strip().partition(":")
        if name.strip() and form.strip() in ("soon", "later"):
            out[name.strip()] = form.strip()
    return out


# D58 moveout (GH #1476, contract points 1 and 5, R-58-9 Nr. 3): THE SIDE
# CALL beside a main call -- the curator's bridge before the move -- is the
# lead's decision: whether one goes, under which condition, to which target
# and with which text. The curator only evaluates the condition and builds
# the window (`side` in the verdict). The texts are knobs, today's sentences
# their shipped values, measured where they stood in `curator/policy`:
#   - one voice for every form (GH #1258): told only "the backend is working
#     on this request", the voice heard a foreign party and said in its own
#     name it could not plan trips (T7, a lab colony, 3.4 s into a consult);
#   - no content on any form (GH #1260, B-L3): the fast model made weather up
#     on the tool round (lab r026c, turn 9) before any lookup;
#   - no talk of missing access (GH #1260, OR-WG-13, B-L6): the tool round's
#     sentence said "I have no access to current weather data" while the
#     lookup ran beside it (lab r026e, turn 9);
#   - the tool round's one sentence asks nothing, a consult only nothing
#     about the request, research goes on with another subject (R-TR-27; told
#     "anything else is fine" it asked about the request in 3 of 5 probe
#     sentences, told to go on with another subject 0 of 10 and 0 of 5, BL6
#     arms C1, C2).
# `{seconds}` and `{minutes}` take the wait of the errand class
# (`departures`); `{fill}` is the curator's gap: it puts the places of the
# tools the cut left open there (`bridge_places`, the words of a family --
# told the tool's code name, the fast model wrote the call out or spoke
# made-up weather in 14 of 30 probe sentences, the words held 0 of 30, BL6
# arms A and B). A form without a text sends no side call.
BRIDGE_TEXTS = dict((str(k), t) for k, t in json_knob("bridge_texts").items()
                    if isinstance(t, str))
# D58 target (contract point 14, OR-d58-2.target.72, .74) moved here: the
# form a class's side call speaks (`soon`: the answer follows in this turn,
# the side call sees the person's turn alone; `later`: the result comes in a
# later turn, the side call keeps the target's window). A class the knob
# does not name speaks `later`.
BRIDGE_WORDING = wording_map(P.get("bridge_wording"))
BRIDGE_PLACES = json_knob("bridge_places")
# Orchestrator ruling moveout.15: the slot a side call's text stands under
# when its target has not reported a profile yet (the first errand of a
# colony goes out beside the target's `catalog_ask`): the curator takes the
# target's own `instructions.side_slot` first, this one else. Shipped
# "bridge", the leaf `instructions.bridge` the bridge spoke under before the
# move, so that first call keeps its side call, byte for byte.
SIDE_SLOT = str(P.get("side_slot") or "").strip()


def route_and_reason(path, consult_id):
    """`(target or class, reason)` of a path: `answer`, `no_path`,
    `no_route` (each the `*` target) or `path`."""
    if consult_id:
        return DEFAULT_ROUTE, "answer"
    if not path:
        return DEFAULT_ROUTE, "no_path"
    if path not in PATH_ROUTES:
        return DEFAULT_ROUTE, "no_route"
    return str(PATH_ROUTES.get(path) or DEFAULT_ROUTE), "path"


def fast(target):
    """Whether `target` is a fast one: the lead names a fallback for it."""
    return bool(target) and bool(FALLBACK.get(target))


def departs_of(name):
    """`{class, wait_ms}` of an errand class, {} for a target."""
    d = DEPARTURES.get(name)
    return {"class": name, "wait_ms": d[0]} if d else {}


def pending_ms(name):
    """How long the mark of an errand of class `name` stands (GH #1260): its
    own `pending_ms` in `departures`, else `consult_pending_ms`."""
    d = DEPARTURES.get(name)
    return d[1] if d and d[1] is not None else CONSULT_PENDING_MS


def bridge_target():
    """The target of a side call (OR-d58-2.target.14): `bridge_target`'s
    `spec` entry while the lead speculates, else its `*` entry."""
    if QUICK_SPECULATIVE and BRIDGE_TARGETS.get("spec"):
        return BRIDGE_TARGETS["spec"]
    return BRIDGE_TARGETS.get("*", "")


def side_entry(when, form, wait_ms):
    """One entry of the verdict's `side` (contract point 1), None when the
    form has no text or `bridge_target` names no target (a side call goes
    only to a named target, OR-d58-2.target.71): `when` the curator's condition, `target` the side
    call's (`bridge_target`), `window` -- `wall` for `later`, else the
    person's turn --, `text` the form's (`bridge_texts`, its wait put in),
    `fill` the places table on the tool round, `first` on `must_call`: the
    side call and the required call go to the same voice, one `handle()` at
    a time, so the sentence leaves first (GH #1260 fix round 1, OR-WG-8)."""
    target = bridge_target()
    text = BRIDGE_TEXTS.get(form, "")
    if not target or not text.strip():
        return None
    text = text.replace("{seconds}", str(max(1, int(round(wait_ms / 1000.0))))) \
        .replace("{minutes}", str(max(1, int(round(wait_ms / 60000.0)))))
    entry = {"when": when, "target": target,
             "window": "wall" if form == "later" else "turn",
             "text": text, "first": when == "must_call"}
    if SIDE_SLOT:
        entry["slot"] = SIDE_SLOT
    if when == "must_call" and BRIDGE_PLACES:
        entry["fill"] = BRIDGE_PLACES
    return entry


def without_consult(scope, folded=()):
    """A speaking call's `tool_scope` while a consult is pending (GH #1280):
    the consult tool denied (its family too when the collector folded it),
    the channel's own allow and deny kept; a scope whose `allow` does not
    hold the tool stays as it is."""
    out = dict(scope) if isinstance(scope, dict) else {}
    if not ERRAND_TOOL or ("allow" in out
                           and not family_in(ERRAND_TOOL, names_list(out.get("allow")))):
        return scope
    deny = names_list(out.get("deny"))
    for name in [n for n in (ERRAND_TOOL, ERRAND_FAMILY) if n]:
        if name not in deny and (name == ERRAND_TOOL or name in folded):
            deny.append(name)
    out["deny"] = deny
    return out
# <<< ways v1


# >>> horizon v2 (#1400, moved from curator/policy by D58 moveout, GH #1476)
# THE VOICE KNOWS WHEN THE ANSWER COMES. `horizon_advise` "1": a running
# session's turn (its handle `live` in the question) whose call leaves the
# composite (an errand class, `external`) or gets its required tool round
# (`must_call`) is told how long the answer takes: ONE entry in the verdict's
# `feed` -- section `horizon`, the body numbers only (`seconds` rounded up,
# `way`, `family`; the sentence is the set's, `horizon_text` of the voice,
# R-LS-2) -- under the same condition as the side call; the curator sends it
# with the round's sends when the condition holds, held and gone with them.
# The seconds are the `horizon_quantile` (default p75, never the median: a
# wait said too short is worse than one said too long, A9) of the rounds of
# the turn's family booked so far, else `horizon_defaults_ms[family]`, else
# nothing is said (and the round is still booked). A turn with several
# families takes the longest, one without a family counts under its way. The
# bookkeeping is this store's (before: the curator's ledger): the verdict
# keeps its plan (`horizon_plan:<session>`, the entry of its turn, its call);
# the curator's note `round` (a condition held; held sends carry it, so it
# counts only when they go) starts the turn's clock at the seam (the entry
# of the turn in `horizon_turn:<session>`); the note `turn_end` with its
# `round_end` books the duration under the family in `horizon_rounds` (the
# newest `HORIZON_KEEP` per family), takes the turn's entry out and
# keeps what was said and how long it took (`horizon_last:<session>`
# `{turn, family, planned, actual}`, seconds; the mark `feed` of the sent
# advise carries `planned` and `family`). `0` (the default): nothing read,
# written or ordered.
HORIZON_ADVISE = switch_on(P.get("horizon_advise"))
HORIZON_SECTION = "horizon"
HORIZON_KEY = "horizon_rounds"
HORIZON_PLAN_KEY = "horizon_plan:"
HORIZON_TURN_KEY = "horizon_turn:"
HORIZON_LAST_KEY = "horizon_last:"
HORIZON_KEEP = 20
# `horizon_plan:<session>` and `horizon_turn:<session>` are tables `{turn:
# row}` (review B M-2 of D58 moveout): two waiting rounds of one session can
# overlap -- a tool round of a turn while the errand of a turn before still
# runs -- and each is booked; one row per session lost the first round's
# clock to the second. A turn whose round never ends (no answer, a hand-over)
# leaves its entry, and this store sweeps nothing, so each table keeps its
# newest HORIZON_TURNS entries (`n`, the order they were written in). 8:
# the overlap is two rounds (an errand runs minutes, the turns beside it are
# tool rounds of seconds); 8 leaves room for a run of unanswered turns and
# keeps the row at a few hundred bytes.
HORIZON_TURNS = 8


def horizon_defaults(v):
    """`horizon_defaults_ms`: family -> milliseconds, a JSON text or an
    object; a value that is no positive number is said and left out."""
    if isinstance(v, str):
        try:
            v = json.loads(v or "{}")
        except ValueError:
            sys.stderr.write("lead/lead: horizon_defaults_ms is no JSON object -- {}\n")
            v = {}
    out = {}
    for k, x in (v.items() if isinstance(v, dict) else []):
        try:
            ms = int(x)
        except (TypeError, ValueError):
            ms = 0
        if ms > 0 and not isinstance(x, bool):
            out[str(k)] = ms
        else:
            sys.stderr.write("lead/lead: horizon_defaults_ms[%r] = %r is no positive"
                             " number of ms -- left out\n" % (k, x))
    return out


def horizon_quantile_of(v):
    """`horizon_quantile`: 51..100; anything else is said and read as 75 --
    never the median (A9)."""
    try:
        q = int(str(v if v is not None else "75").strip())
    except ValueError:
        q = 0
    if not 50 < q <= 100:
        sys.stderr.write("lead/lead: horizon_quantile %r is not in 51..100 -- 75\n" % (v,))
        q = 75
    return q


HORIZON_DEFAULTS = horizon_defaults(P.get("horizon_defaults_ms")) if HORIZON_ADVISE else {}
HORIZON_QUANTILE = horizon_quantile_of(P.get("horizon_quantile")) if HORIZON_ADVISE else 75


def quantile_ms(values, q):
    """The nearest-rank `q`-th percentile of `values` (ms), None for none."""
    vs = sorted(int(x) for x in values or []
                if isinstance(x, (int, float)) and not isinstance(x, bool) and x >= 0)
    if not vs:
        return None
    return vs[max(0, -(-q * len(vs) // 100) - 1)]


def horizon_plan(families, rounds):
    """`(family, ms)` of a turn: per family the quantile of its booked
    rounds, else its default; the longest wins. `ms` None when no family has
    either (nothing is said, the round is still booked under the first
    family)."""
    best = None
    for f in families:
        booked = rounds.get(f) if isinstance(rounds, dict) else None
        ms = quantile_ms(booked, HORIZON_QUANTILE) if isinstance(booked, list) else None
        if ms is None:
            ms = HORIZON_DEFAULTS.get(f)
        if ms is not None and (best is None or ms > best[1]):
            best = (f, ms)
    return best or (families[0] if families else "", None)


def horizon_of(when, way, families, rounds):
    """`(feed entries, plan)` of a turn under `when` (`external` with the
    errand class as its way, `must_call` with the fast target): the plan
    `{when, family, way, seconds}` the store keeps, and the advise when its
    seconds are known."""
    fam, ms = horizon_plan(families or [way], rounds)
    secs = None if ms is None else -(-int(ms) // 1000)
    plan = {"when": when, "family": fam, "way": way, "seconds": secs}
    if secs is None:
        return [], plan
    return [{"when": when, "section": HORIZON_SECTION,
             "body": {"section": HORIZON_SECTION, "seconds": secs, "way": way, "family": fam},
             "mark": {"planned": secs, "family": fam}}], plan


def turn_table(text):
    """A table `{turn: row}` of this store (`horizon_plan:`,
    `horizon_turn:`), {} for none."""
    return {str(k): v for k, v in jd(text).items() if isinstance(v, dict)}


def table_put(text, turn, row):
    """The table `text` with `row` as the entry of `turn`, the newest
    HORIZON_TURNS kept."""
    t = turn_table(text)
    t.pop(turn, None)
    n = max([r["n"] for r in t.values() if isinstance(r.get("n"), int)] + [0]) + 1
    t[turn] = dict(row, n=n)
    newest = sorted(t, key=lambda k: t[k]["n"] if isinstance(t[k].get("n"), int) else 0)
    return {k: t[k] for k in newest[-HORIZON_TURNS:]}


def table_ops(cid, key, text, table):
    """The write of a table read as `text`, compare-and-set on that value:
    a new row only where none stands, an emptied one deleted. Lost to a
    write between, it is left -- the other write is as true."""
    if not text:
        return [(cid, {"operation": "insert", "table": "state",
                       "row": {"key": key, "value": canonical(table)},
                       "if_absent": {"key": key}})] if table else []
    if not table:
        return [(cid, {"operation": "delete", "table": "state",
                       "where": {"key": key, "value": text}})]
    return [(cid, upd("state", {"value": canonical(table)}, {"key": key, "value": text}))]


def horizon_booked(rounds, family, ms):
    """`horizon_rounds` with one more duration of `family`, the newest
    `HORIZON_KEEP` kept."""
    rounds = rounds if isinstance(rounds, dict) else {}
    booked = [x for x in (rounds.get(family) or []) if isinstance(x, int)] \
        if isinstance(rounds.get(family), list) else []
    return dict(rounds, **{family: (booked + [ms])[-HORIZON_KEEP:]})
# <<< horizon v2


# >>> quick_spec v1 (GH #1275, moved from curator/policy by GH #1447)
def spec_key(kind, session, turn):
    """The rows of a turn's speculation: `spec` (its state), `spec_held` (the
    held answer), `spec_fb` (the stored normal call), `spec_shown`."""
    return "%s:%s#%s" % (kind, session, turn)


def call_name(el):
    """The tool name of a `tool_call` element (its `name`, else its JSON text)."""
    if not isinstance(el, dict):
        return ""
    if el.get("name"):
        return str(el.get("name"))
    v = loads(str(el.get("text") or ""), {})
    return str(v.get("name") or "") if isinstance(v, dict) else ""


def spec_called(held):
    return str(held.get("finish") or "") == "tool_calls" or any(
        isinstance(m, dict) and m.get("type") == "tool_call"
        for m in held.get("messages") or [])


def spec_called_names(held):
    return [n for n in (call_name(m) for m in held.get("messages") or []
                        if isinstance(m, dict) and m.get("type") == "tool_call") if n]


def spec_verdict(held, needs, families=()):
    """`(keep, reason)` of a held answer for a quick turn: no answer is
    dropped; a turn that needs a tool keeps only an answer that called one,
    and every family its stamp names (#1366)."""
    if not held.get("answer"):
        return False, "no_answer"
    if "tool" in needs and not spec_called(held):
        return False, "no_tool_call"
    if "tool" in needs:
        called = spec_called_names(held)
        for f in families:
            if not family_in(f, SPEC_TOOLS) or not any(
                    family_in(n, [f]) or family_in(f, [n]) for n in called):
                return False, "family:" + f
    return True, "kept"


def spec_doomed(needs, families=()):
    """GH #1398: the reason a quick turn drops its spec answer whatever it
    says -- a needed family outside `spec_tools`. None while it can decide."""
    if "tool" in needs:
        for f in families:
            if not family_in(f, SPEC_TOOLS):
                return "family:" + f
    return None
# <<< quick_spec v1


# >>> spec automaton v1 (GH #1275/#1279/#1411/#1432, moved from curator/policy by GH #1447)
# The rows of a turn's speculation and of its delta live here; every move of
# them is an insert-if-absent or a compare-and-set in `./state`. What a
# move means for the ledger and the sends (`quick_spec` marks, bookings, the
# release, the stored call) the lead hands to the policy as `spec_act` on
# `lead_verdict` -- the policy writes and sends, the lead decides.
DELTA_KEY = "delta:"
DELTA_FB_KEY = "delta_fb:"


def jd(text):
    """A JSON object from a row value, {} for anything else."""
    v = loads(text, {})
    return v if isinstance(v, dict) else {}


def sel(table, columns, where=None):
    a = {"operation": "select", "table": table, "columns": columns}
    if where:
        a["where"] = where
    return a


def upd(table, values, where):
    return {"operation": "update", "table": table, "set": values, "where": where}


def ins(table, row):
    return {"operation": "insert", "table": table, "row": row}


def legs(body):
    """The legs of a store answer: payload, error_code, rows_affected per id."""
    out = {}
    for m in body.get("messages") or []:
        if isinstance(m, dict):
            out[str(m.get("id") or "")] = {"payload": loads(str(m.get("text") or "null"), None),
                                           "error_code": "", "rows_affected": 0}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": "", "rows_affected": 0})
                leg["error_code"] = str(r.get("error_code") or "")
                leg["rows_affected"] = int(r.get("rows_affected") or 0)
    elif len(out) == 1:
        leg = next(iter(out.values()))
        leg["error_code"] = str(hop.get("error_code") or "")
        leg["rows_affected"] = int(hop.get("rows_affected") or 0)
    return out


def state_of(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return {str(r.get("key") or ""): str(r.get("value") or "")
            for r in (p if isinstance(p, list) else []) if isinstance(r, dict)}


def report_errors(lg):
    for cid, leg in lg.items():
        if leg.get("error_code"):
            sys.stderr.write("lead/lead: store leg %s failed (%s)\n"
                             % (cid, leg["error_code"]))


def shown_text(messages):
    """GH #1432: the text a spec partial showed -- its assistant text."""
    return "\n\n".join(str(m.get("text") or "") for m in messages or []
                         if isinstance(m, dict) and m.get("type") == "text"
                         and str(m.get("origin") or "assistant") == "assistant"
                         and str(m.get("text") or "").strip())


def act(call, a):
    """The ledger's and the sends' share of a move, for the policy."""
    return {"header": {"route": "lead_verdict", "call": call}, "messages": [], "spec_act": a}


def spec_settle(call, session, turn, raw, row, held, fb, shown=None, rnd=None, go=None):
    """The awaited decision, once the held answer is in: keep -- release it;
    drop -- the stored normal call goes. The row moves from `await` by CAS:
    only the answer of the spec call acts on an awaiting row. GH #1432:
    `shown` is the turn's `spec_shown` row: a kept answer takes it down, a
    dropped one hands its text to the stored call (`with_shown`, policy)."""
    keep, why = spec_verdict(held, names_list(fb.get("needs")), names_list(fb.get("families")))
    ops = [("s-set", {"operation": "delete", "table": "state",
                      "where": {"key": spec_key("spec", session, turn), "value": raw}}),
           ("s-dh", {"operation": "delete", "table": "state",
                     "where": {"key": spec_key("spec_held", session, turn)}}),
           ("s-dfb", {"operation": "delete", "table": "state",
                      "where": {"key": spec_key("spec_fb", session, turn)}})]
    shown = shown if isinstance(shown, dict) else {}
    s_text = str(shown.get("text") or "") if str(shown.get("call") or "") == call else ""
    if keep and shown:
        ops.append(("s-dsh", {"operation": "delete", "table": "state",
                              "where": {"key": spec_key("spec_shown", session, turn)}}))
    # D58 note (GH #1477): what the spec call's window showed (`spec_go`) goes
    # to the curator with a kept answer and ends with the row either way.
    go = go if isinstance(go, dict) else {}
    if go:
        ops.append(("s-dgo", {"operation": "delete", "table": "state",
                              "where": {"key": spec_key("spec_go", session, turn)}}))
    a = {"do": "settle", "keep": keep, "why": why, "row": row, "held": held,
         "fb": fb, "s_text": s_text, "s": session, "t": turn, "round": rnd,
         "shown_gone": bool(keep and shown)}
    if keep and go and str(go.get("call") or "") == call:
        a["go"] = go
    return [lstore(ops, "done", call, ""), act(call, a)]
# <<< spec automaton v1


# >>> interrupt-early v2 (#1404, moved from curator/policy by GH #1447; an
# order on `in_feed` since D58 moveout, GH #1476)
# `interrupt_on_delta` "1": the first delta stamp of a voice turn whose
# `choices.risk` value has a question in `interrupt_questions` (crisis value
# -> question) interrupts at once. The lead ORDERS it like any domain (D58
# moveout, contract point 8): one message on the curator's lane `in_feed`,
# section `interrupt`, `once` `interrupt`, `sender` "lead", the handle
# `live`, `session_id`, `turn_id` and the round (`audience_set`) in the head,
# the question as the assistant's text and `mark {delta_n}` (the words of the
# partial) in the body; the curator's claim `pending:feed:<live>#<turn>#
# interrupt` keeps it to one per turn and its mark `feed` books it. As many
# runs as before: policy -> lead -> policy (`in_feed`) -> ledger (claim) ->
# policy (send), where it was policy -> lead -> policy (`spec_act` "ie") ->
# ledger -> policy. A question without a handle is still ordered: the
# curator books it as not sent (`feed {reason: no_live}`). A fallback stamp
# other than `unsure` (GH #1407) is never ordered; its reason
# (`fallback:<value>`) is kept here, in `interrupt:<session>#<turn>`, the
# row that also keeps when and on how many words the order went
# (`at`, `delta_n`, `live`) and, at the turn's first normal ask, how early
# the ORDER went before the turn's end (`turn_end_at`, `ms_before_turn_end`)
# -- whether the curator sent it is the curator's mark `feed`. A row without
# an order (a fallback, or no handle) gives way to the turn's first real
# order (compare-and-set, phase `ie-row`); a real order's row stays. Before
# the move the curator's marks `interrupt_skipped` and `interrupt_early`.
INTERRUPT_KEY = "interrupt:"
INTERRUPT_ONCE = "interrupt"
FEED_LANE = "in_feed"


def interrupt_questions(v):
    """`interrupt_questions`: crisis value -> question, a JSON text or an
    object; an entry without words is said on stderr and left out."""
    if isinstance(v, str):
        try:
            v = json.loads(v or "{}")
        except ValueError:
            v = None
    if not isinstance(v, dict):
        sys.stderr.write("lead/lead: interrupt_questions is no JSON object -- {}\n")
        return {}
    out = {}
    for k, q in v.items():
        if isinstance(q, str) and q.strip():
            out[str(k)] = q
        else:
            sys.stderr.write("lead/lead: interrupt_questions[%r] has no question -- left"
                             " out\n" % k)
    return out


INTERRUPT_QUESTIONS = interrupt_questions(P.get("interrupt_questions")) \
    if INTERRUPT_ON_DELTA else {}


def early_interrupt(ds, turn, hop, ctx, rnd=None):
    """The order of the `interrupt` a delta stamp brings (GH #1404), or None:
    only a value of the route's own judgement that has a question. A
    fallback other than `unsure` (GH #1407) is the text `fallback:<value>`
    -- never ordered, its reason kept. The order carries the handle of the
    running session (`live`, the composition's, D58 live; "" without one:
    the curator books it as not sent), the turn, the session and the round
    (`rnd`) in its head and the words of the partial as its `mark`."""
    if not INTERRUPT_QUESTIONS or not turn:
        return None
    i_fallback = str(hop.get("fallback") or "")
    choices = ds.get("choices") if isinstance(ds.get("choices"), dict) else {}
    risk = choices.get("risk")
    if not isinstance(risk, dict) or str(risk.get("source") or "") == "fallback":
        return None
    question = INTERRUPT_QUESTIONS.get(str(risk.get("value") or ""))
    if not question:
        return None
    if i_fallback not in ("", "unsure"):
        return "fallback:" + i_fallback
    head = {"route": FEED_LANE, "section": "interrupt",
            "live": str(hop.get("live") or ctx.get("live") or ""),
            "session_id": str(ctx.get("session_id") or hop.get("session_id") or ""),
            "turn_id": turn, "sender": ME, "once": INTERRUPT_ONCE}
    if rnd is not None:
        head["audience_set"] = rnd
    return {"header": head,
            "messages": [{"origin": "assistant", "type": "text", "text": question}],
            "mark": {"delta_n": len(str(ds.get("text_norm") or "").split())}}


def interrupt_row(order, at):
    """The row `interrupt:<session>#<turn>` of an order (or of the reason
    none went): when, on how many words, under which handle."""
    if isinstance(order, str):
        return {"at": at, "skip": order}
    return {"at": at, "delta_n": order["mark"]["delta_n"],
            "live": order["header"]["live"]}


def interrupt_end(raw, head):
    """The update of the turn's interrupt row at its first normal ask (the
    turn's end: iteration 0, no spec) -- how early the order went before it,
    `ms_before_turn_end` -- or [] (no row, no order, or booked already). A
    row whose order had no handle went nowhere and is left as it is."""
    session, turn = str(head.get("session") or ""), str(head.get("turn") or "")
    if not INTERRUPT_ON_DELTA or not turn or str(head.get("spec") or "") == "1" \
            or str(head.get("iter") or "0") != "0":
        return []
    key = INTERRUPT_KEY + "%s#%s" % (session, turn)
    i_raw = raw.get(key, "")
    row = jd(i_raw)
    at, end = str(row.get("at") or ""), str(head.get("at") or "")
    if not at or not end or row.get("skip") or not row.get("live") \
            or "ms_before_turn_end" in row:
        return []
    ms = max(0, (epoch_us(end) - epoch_us(at)) // 1000)
    return [("l-ie-end", upd("state", {"value": canonical(dict(
        row, turn_end_at=end, ms_before_turn_end=ms))}, {"key": key, "value": i_raw}))]
# <<< interrupt-early v2


def lead_verdict(stamp, head, state):
    """THE ONE DECISION of the lead: the route stamp (`path`, `needs`,
    `families`), the turn's head and the lead's own rows in, the verdict out:
    `{target, fallback, departs, side, feed, reason, spec}`
    and what the policy
    needs to build on it (`escalate` and the target it fell `from`, `speak_check`, `pending`, `deny`,
    `spec_row`, `spec_held`, `spec_needs`, `spec_families`), and the plan of
    the turn's waiting time the lead keeps (`wait`, `horizon v2`)."""
    stamp = stamp if isinstance(stamp, dict) else {}
    head = head if isinstance(head, dict) else {}
    state = state if isinstance(state, dict) else {}
    call = str(head.get("call") or "")
    turn = str(head.get("turn") or "")
    path = str(stamp.get("path") or "").strip()
    needs = names_list(stamp.get("needs"))
    families = names_list(stamp.get("families"))
    answered = str(head.get("consult_id") or "")
    try:
        it = int(str(head.get("iter") or "0"))
    except ValueError:
        it = 0
    is_spec = str(head.get("spec") or "") == "1"
    esc_flag = str(head.get("escalate") or "")
    target, reason = route_and_reason(path, answered)
    departs = departs_of(target)
    if departs:
        target = ""
    if MEMORY_TO_BRAIN and fast(target) and not answered and "memory" in needs:
        target, reason = FALLBACK[target], "memory"
    way_reason = "memory" if reason == "memory" else ""
    escalate, speak_check = "", False
    # The target a fallback took the round from (the `escalate` mark's `from`).
    fell_from = ""
    if esc_flag:
        fell_from = target if FALLBACK.get(target) else ""
        target, escalate = FALLBACK.get(target) or target, esc_flag
        departs = {}
        reason = "escalate:" + esc_flag
    elif fast(target) and it >= 1 and str(state.get("escalated") or "") == turn:
        target, reason = FALLBACK[target], "escalated"
    elif fast(target) and it >= 1:
        if it > QUICK_MAX_ITER:
            fell_from = target
            target, escalate, reason = FALLBACK[target], "iterations", "iterations"
        else:
            speak_check = True
    s_row = state.get("spec") if isinstance(state.get("spec"), dict) else {}
    s_held = state.get("spec_held") if isinstance(state.get("spec_held"), dict) else {}
    s_state = str(s_row.get("state") or "")
    spec = ""
    if is_spec and not (QUICK_SPECULATIVE and SPEC_TARGET):
        spec = "parked"
    elif is_spec:
        if s_row and str(s_row.get("call") or "") != call:
            spec = "parked:decided"
        elif s_state != "await" and state.get("called"):
            spec = "parked:called"
        else:
            reason, escalate, speak_check = "spec", "", False
            spec, target, departs = "call", SPEC_TARGET, {}
    elif s_row and s_state == "delta" and str(s_row.get("call") or "") != call \
            and not esc_flag:
        spec = "parked:delta"
    elif s_row and str(s_row.get("call") or "") != call and not esc_flag \
            and s_state in ("fired", "held"):
        if way_reason:
            spec = "dropped:" + way_reason
        elif not fast(target):
            spec = "dropped:path:" + (path or "none")
        elif s_state == "held":
            keep, why = spec_verdict(s_held, needs, families)
            spec = "kept" if keep else "dropped:" + why
        elif spec_doomed(needs, families):
            spec = "dropped:" + spec_doomed(needs, families)
        else:
            spec = "wait"
    # D58 moveout (contract point 1): the side calls beside the call, each
    # under a condition the curator evaluates -- `external` when the main
    # call leaves the composite, `must_call` when the cut gives the call its
    # required tool round (only the cut knows the round's tools). A call that
    # leaves names no `must_call` entry (OR-d58-2.moveout.6): one side call
    # per call, as before the move.
    side = []
    if departs:
        side = [side_entry("external", BRIDGE_WORDING.get(departs["class"], "later"),
                           departs["wait_ms"])]
    elif fast(target) and "tool" in needs and it < 1 and not is_spec:
        side = [side_entry("must_call", "tool", 0)]
    side = [e for e in side if e]
    # D58 moveout (contract point 6): the conditional feeds -- the waiting-
    # time advise of a running session's first call of a turn, under the
    # side call's condition (`horizon v2`).
    feed, wait = [], {}
    if HORIZON_ADVISE and str(head.get("live") or "") and not is_spec and it == 0:
        if departs:
            feed, wait = horizon_of("external", departs["class"], families,
                                    state.get("horizon_rounds"))
        elif fast(target) and "tool" in needs:
            feed, wait = horizon_of("must_call", target, families, state.get("horizon_rounds"))
    pending = state.get("consult_pending") if isinstance(state.get("consult_pending"),
                                                         dict) else {}
    at = str(head.get("at") or "")
    asked_back = str(head.get("consult_class") or "") == "ask"
    pending_end = ""
    if pending and answered and pending.get("consult_id") == answered and not asked_back:
        pending, pending_end = {}, "advice"
    elif pending and str(pending.get("until") or "") <= at:
        pending, pending_end = {}, "lapsed"
    deny = names_list(without_consult({}, names_list(head.get("tools_folded")))
                      .get("deny")) if pending and not departs else []
    return {"target": target, "fallback": FALLBACK.get(target, "") if target else "",
            "departs": departs, "side": side, "feed": feed, "wait": wait,
            "reason": reason, "spec": spec,
            "escalate": escalate, "from": fell_from if escalate else "",
            "speak_check": speak_check, "pending": pending,
            "pending_end": pending_end, "deny": deny,
            "spec_row": s_row, "spec_held": s_held}


def spec_window(v, a, raw, state):
    """What the policy builds the window on beyond the verdict (GH #1447):
    the raw speculation row (its compare-and-set), the delta stamp of a spec
    curate, the shown spec sentence of an escalation, and the knob values
    the window itself needs (`quick_speculative`, `spec_tools`). D58
    moveout: no `interrupt_on_delta` -- the interrupt is the lead's order,
    the curator reads nothing of it."""
    session, turn = str(a.get("session") or ""), str(a.get("turn") or "")
    call = str(a.get("call") or "")
    out = {"spec_raw": raw.get(spec_key("spec", session, turn), ""),
           "quick_speculative": QUICK_SPECULATIVE,
           "spec_tools": list(SPEC_TOOLS) if v.get("spec") == "call" else [],
           "shown": "", "delta": {}}
    s_go = state.get("spec_go") if isinstance(state.get("spec_go"), dict) else {}
    if v.get("spec") == "kept" and s_go \
            and str(s_go.get("call") or "") == str((v.get("spec_held") or {}).get("call") or ""):
        # D58 note (GH #1477): the kept answer's window showed `once` notes --
        # their use and receipts go with it (the policy's `kept` branch).
        out["spec_go"] = s_go
    if QUICK_SPECULATIVE and a.get("escalate"):
        out["shown"] = str(jd(raw.get(spec_key("spec_shown", session, turn), "")).get("text")
                           or "")
    d_raw = raw.get(DELTA_KEY + turn, "")
    if DELTA_SPEC and QUICK_SPECULATIVE and str(a.get("spec") or "") == "1" and d_raw:
        d_val = jd(d_raw)
        d_stamp = d_val.get("stamp") if isinstance(d_val.get("stamp"), dict) else {}
        claim = state.get("spec") if isinstance(state.get("spec"), dict) else {}
        d_path = str(d_stamp.get("path") or "")
        out["delta"] = {
            "raw": d_raw, "stamp": d_stamp,
            "ok": str(claim.get("call") or "") == call
            and str(claim.get("state") or "") == "fired" and not state.get("called"),
            # GH #1435 (K7 review I-1): a delta whose turn leaves on brain for
            # its memory is refired.
            "memory": MEMORY_TO_BRAIN
            and fast(route_and_reason(d_path, "")[0])
            and "memory" in names_list(d_stamp.get("needs"))}
    return out


def lead_writes(v, head, raw):
    """The writes of a verdict in the lead's own store: the escalation row,
    the errand's mark (ended, lapsed or set), the speculation rows and the
    turn's end on its interrupt row."""
    session = str(head.get("session") or "")
    turn = str(head.get("turn") or "")
    call = str(head.get("call") or "")
    at = str(head.get("at") or "")
    ops = []
    if v["escalate"]:
        ops += put("l-esc", "escalated:" + session, turn)
    if v["pending_end"] == "advice":
        ops.append(("l-cpend", {"operation": "delete", "table": "state",
                                "where": {"key": "consult_pending:" + session}}))
    elif v["pending_end"] == "lapsed":
        ops.append(("l-cpexp", {"operation": "delete", "table": "state",
                                "where": {"key": "consult_pending:" + session,
                                          "value": raw.get("consult_pending:" + session, "")}}))
    if v["departs"]:
        cid = "k-" + call
        ops += put("l-cpput", "consult_pending:" + session,
                   canonical({"consult_id": cid, "turn": turn, "path": head.get("path", ""),
                              "at": at, "wait_ms": v["departs"]["wait_ms"],
                              "until": stamp_after(at, pending_ms(v["departs"]["class"]))}))
    s_raw = raw.get(spec_key("spec", session, turn), "")
    if v["spec"].startswith("dropped:") or v["spec"] == "kept":
        ops += [("l-sdrop", {"operation": "delete", "table": "state",
                             "where": {"key": spec_key("spec", session, turn)}
                             if v["spec"] != "kept" else
                             {"key": spec_key("spec", session, turn), "value": s_raw}}),
                ("l-sdh", {"operation": "delete", "table": "state",
                           "where": {"key": spec_key("spec_held", session, turn)}})]
        if raw.get(spec_key("spec_go", session, turn)):
            # D58 note (GH #1477): the spec call's held writes end with its row.
            ops.append(("l-sdgo", {"operation": "delete", "table": "state",
                                   "where": {"key": spec_key("spec_go", session, turn)}}))
    elif v["spec"] == "parked:called":
        ops.append(("l-sown", {"operation": "delete", "table": "state",
                               "where": {"key": spec_key("spec", session, turn),
                                         "value": s_raw}}))
    elif v["spec"] == "parked:delta":
        ops += [("l-sdone", {"operation": "delete", "table": "state",
                             "where": {"key": spec_key("spec", session, turn), "value": s_raw}}),
                ("l-ddel", {"operation": "delete", "table": "state",
                            "where": {"key": "delta:" + turn}})]
    if QUICK_SPECULATIVE and turn and str(head.get("spec") or "") != "1" \
            and str(head.get("iter") or "0") == "0" and not head.get("escalate"):
        # OR-d38-3.c1.8: the turn's normal verdict is given -- a spec curate
        # after it parks (the ledger's `calls` row of before). One row per
        # session with its last `spec_called_turns` turns (OR-d38-3.c1.40,
        # c1.44): a row per turn was never taken down, the newest turn alone
        # let a late spec curate of the turn before through.
        ops += put("l-called", SPEC_CALLED_KEY + session,
                   canonical(called_add(raw.get(SPEC_CALLED_KEY + session, ""), turn, call)))
    if v.get("wait"):
        # D58 moveout (contract point 7): the plan of the turn's waiting time,
        # for the note `round` of this very call -- the turn's entry of the
        # session's table (review B M-2).
        p_key = HORIZON_PLAN_KEY + session
        ops += table_ops("l-hzplan", p_key, raw.get(p_key, ""),
                         table_put(raw.get(p_key, ""), turn, dict(v["wait"], call=call)))
    # D58 moveout (contract point 9): how early the turn's order of the
    # interrupt went, in the lead's own row (before: the curator's mark
    # `interrupt_early`, written only when the interrupt was sent).
    ops += interrupt_end(raw, head)
    ops += put("l-verdict", "verdict:" + session, canonical({"call": call, "verdict": v}))
    return ops


# OR-d38-3.c1.40: the call that got the session's newest normal verdict.
SPEC_CALLED_KEY = "spec_called:"


def called_rows(raw):
    """The session's `[{turn, call}]`, oldest first; anything else is none."""
    rows = loads(raw, [])
    return [r for r in (rows if isinstance(rows, list) else [])
            if isinstance(r, dict) and str(r.get("turn") or "")]


def called_add(raw, turn, call):
    """The session's rows with `turn` -> `call` as the newest, the oldest
    beyond `spec_called_turns` dropped."""
    rows = [r for r in called_rows(raw) if str(r.get("turn") or "") != turn]
    rows.append({"turn": turn, "call": call})
    return rows[-SPEC_CALLED_TURNS:]


def called_other(raw, turn, call):
    """True when another call of `turn` already got the turn's normal verdict."""
    return any(str(r.get("turn") or "") == turn and str(r.get("call") or "") not in ("", call)
               for r in called_rows(raw))


def put(cid, key, value):
    """An unconditional set of a state row in ONE step (`replace`)."""
    return [(cid, {"operation": "insert", "table": "state",
                   "row": {"key": key, "value": value}, "replace": {"key": key}})]


def lstore(ops, phase, call="", reason=""):
    return {"header": {"route": "lstore", "phase": phase, "reply_cell": ME,
                       "cur_call": call, "cur_reason": reason},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def ask_keys(a):
    session, turn = str(a.get("session") or ""), str(a.get("turn") or "")
    return ["escalated:" + session, "consult_pending:" + session,
            spec_key("spec", session, turn), spec_key("spec_held", session, turn),
            spec_key("spec_go", session, turn),
            SPEC_CALLED_KEY + session, spec_key("spec_shown", session, turn),
            DELTA_KEY + turn, "verdict:" + session] \
        + ([HORIZON_KEY, HORIZON_PLAN_KEY + session] if HORIZON_ADVISE else []) \
        + ([INTERRUPT_KEY + "%s#%s" % (session, turn)] if INTERRUPT_ON_DELTA and turn else [])


def handle_ms():
    return int((time.perf_counter() - T0) * 1000)


def emit(msgs):
    sys.stdout.write(json.dumps(list(msgs)))
    sys.exit(0)


if True:
    lane = str(hop.get("route") or "")
    phase = str(ctx.get("cur_phase") or "")
    if lane == "lead_ask":
        a = d.get("ask") if isinstance(d.get("ask"), dict) else {}
        session, turn = str(a.get("session") or ""), str(a.get("turn") or "")
        call = str(a.get("call") or "")
        if a.get("read") == "errand":
            # GH #1447: a rebuild of the policy asks for the session's errand
            # (the summarizer's state line); nothing is decided or written.
            emit([lstore([("l-err", {"operation": "select", "table": "state",
                                     "columns": ["key", "value"],
                                     "where": {"key": "consult_pending:" + session}})],
                         "errand", call, canonical(a))])
        ops = []
        if QUICK_SPECULATIVE and turn and str(a.get("iter") or "0") == "0" \
                and not a.get("escalate") and not a.get("again"):
            # GH #1275: the iteration 0 of a turn claims the turn's spec row
            # (insert-if-absent): a spec curate as `fired`, a normal one as
            # `normal`; whoever is first owns it.
            s_k = spec_key("spec", session, turn)
            claim = {"call": call, "state": "fired", "fired_at": a.get("at", "")} \
                if str(a.get("spec") or "") == "1" else {"call": call, "state": "normal"}
            ops.append(("l-spec", {"operation": "insert", "table": "state",
                                   "row": {"key": s_k, "value": canonical(claim)},
                                   "if_absent": {"key": s_k}}))
        ops.append(("l-rows", {"operation": "select", "table": "state",
                               "columns": ["key", "value"],
                               "where": {"key": {"in": ask_keys(a)}}}))
        emit([lstore(ops, "ask", call, canonical(dict(a, ask_ms=handle_ms())))])
    if lane == "lead_spec":
        e = d.get("event") if isinstance(d.get("event"), dict) else {}
        kind = str(e.get("kind") or "")
        session, turn = str(e.get("s") or ""), str(e.get("t") or "")
        call = str(e.get("call") or "")
        rnd = e.get("round")
        if kind == "delta_stamp":
            # GH #1279: the stamp of a delta of a turn, kept for the turn's
            # spec curate (the newest wins). GH #1404: a crisis value with a
            # question interrupts at once, with or without delta_speculation.
            ds = e.get("stamp") if isinstance(e.get("stamp"), dict) else {}
            e_hop = e.get("hop") if isinstance(e.get("hop"), dict) else {}
            e_ctx = e.get("ctx") if isinstance(e.get("ctx"), dict) else {}
            ie_order = early_interrupt(ds, turn, e_hop, e_ctx, rnd) \
                if INTERRUPT_ON_DELTA else None
            if not DELTA_SPEC and ie_order is None:
                sys.stderr.write("lead/lead: a delta stamp of turn %r while"
                                 " delta_speculation is off -- parked\n" % turn)
                emit([])
            if not turn or not str(ds.get("text_norm") or ""):
                sys.stderr.write("lead/lead: a delta stamp without its turn or its text"
                                 " -- dropped\n")
                emit([])
            out = []
            if DELTA_SPEC:
                keep = {k: ds[k] for k in ("path", "p", "intent", "needs", "families",
                                            "choices", "turn_notes", "text_norm") if k in ds}
                out.append(lstore(put("d-put", DELTA_KEY + turn,
                                      canonical({"stamp": keep, "at": e.get("at", "")})),
                                  "done", "", ""))
            if ie_order is not None:
                # D58 moveout (contract point 8): the order goes on
                # `in_feed` (the curator's claim keeps it once per turn); a
                # fallback is never ordered. The turn's row says the reason,
                # or when and on how many words the order went: a row without
                # an order (a fallback, no handle) only where none stands
                # (`if_absent`); a real order reads the row first and takes
                # the place of one without an order (review B M-1: the first
                # stamp a fallback, a later one ordered -- the row kept the
                # fallback and lost how early the real order went). The order
                # itself leaves at once, beside the read.
                ie_session = str(e_ctx.get("session_id") or e_hop.get("session_id") or "")
                ie_key = INTERRUPT_KEY + "%s#%s" % (ie_session, turn)
                ie_row = interrupt_row(ie_order, e.get("at", ""))
                if isinstance(ie_order, str):
                    sys.stderr.write("lead/lead: no early interrupt of turn %r (%s) -- not"
                                     " ordered\n" % (turn, ie_order))
                if ie_row.get("live"):
                    out.append(lstore([("i-read", sel("state", ["key", "value"],
                                                      {"key": ie_key}))],
                                      "ie-row", "", canonical({"key": ie_key, "row": ie_row})))
                else:
                    out.append(lstore([("i-row", {"operation": "insert", "table": "state",
                                                  "row": {"key": ie_key,
                                                          "value": canonical(ie_row)},
                                                  "if_absent": {"key": ie_key}})],
                                      "done", "", ""))
                if isinstance(ie_order, dict):
                    out.append(ie_order)
            emit(out)
        if not QUICK_SPECULATIVE or not call or not turn:
            sys.stderr.write("lead/lead: a spec %s (call %r) with quick_speculative off or"
                             " without its turn -- dropped\n" % (kind, call))
            emit([])
        if kind == "part":
            # GH #1411 / #1415: a sentence of a spec call while it still
            # streams -- the row and its stored fallback are read once.
            emit([lstore([("p-read", sel("state", ["key", "value"], {"key": {"in": [
                spec_key(k, session, turn) for k in ("spec", "spec_fb", "spec_shown")]}}))],
                "spec-part", call, canonical({"s": session, "t": turn, "hop": e.get("hop"),
                                              "messages": e.get("messages") or [],
                                              "round": rnd}))])
        if kind == "ans":
            # GH #1275: the quick voice answered a spec call. Held, never
            # passed on: put beside the turn's row, the row read back.
            s_held = e.get("held") if isinstance(e.get("held"), dict) else {}
            out = [act(call, {"do": "book", "use": e.get("use") or {}})] if e.get("use") else []
            emit(out + [lstore(put("h-held", spec_key("spec_held", session, turn),
                                   canonical(s_held))
                               + [("h-read", sel("state", ["key", "value"], {"key": {"in": [
                                   spec_key(k, session, turn)
                                   for k in ("spec", "spec_held", "spec_fb", "spec_go")]}})),
                                  ("h-shown", sel("state", ["key", "value"],
                                                  {"key": spec_key("spec_shown", session, turn)}))],
                               "spec-ans", call,
                               canonical({"s": session, "t": turn, "n": 0, "round": rnd}))])
        if kind == "fb":
            # GH #1275: the built call is the fallback of an awaited spec
            # answer -- stored, the row moved to `await` by CAS.
            s_fb = {"sends": e.get("sends") or [], "needs": e.get("needs") or []}
            if e.get("go_ops"):
                s_fb["go_ops"] = e.get("go_ops")
            if e.get("families"):
                s_fb["families"] = e.get("families")
            raw = str(e.get("raw") or "")
            row = jd(raw)
            emit([lstore(put("f-sfb", spec_key("spec_fb", session, turn), canonical(s_fb))
                         + [("f-sawait", upd("state", {"value": canonical(dict(row, state="await"))},
                                             {"key": spec_key("spec", session, turn),
                                              "value": raw})),
                            ("f-sread", sel("state", ["key", "value"], {"key": {"in": [
                                spec_key(k, session, turn)
                                for k in ("spec", "spec_held", "spec_fb", "spec_go")]}}))],
                         "spec-await", call, canonical({"s": session, "t": turn, "round": rnd}))])
        if kind == "delta_fb":
            # GH #1279: the reused call is stored and the row moved `fired` ->
            # `delta` by CAS; `delta-send` sends it only when the move took.
            raw = str(e.get("raw") or "")
            d_fb = {"sends": e.get("sends") or []}
            if e.get("go_ops"):
                d_fb["go_ops"] = e.get("go_ops")
            fb_key = DELTA_FB_KEY + "%s#%s" % (session, turn)
            emit([lstore([("f-ddel", {"operation": "delete", "table": "state",
                                      "where": {"key": DELTA_KEY + turn,
                                                "value": str(e.get("delta_raw") or "")}})]
                         + put("f-dfb", fb_key, canonical(d_fb))
                         + [("f-sdelta", upd("state",
                                             {"value": canonical(dict(jd(raw), state="delta"))},
                                             {"key": spec_key("spec", session, turn),
                                              "value": raw})),
                            ("f-dread", sel("state", ["key", "value"], {"key": {"in": [
                                spec_key("spec", session, turn), spec_key("spec_fb", session, turn),
                                fb_key]}}))],
                         "delta-send", call, canonical({"s": session, "t": turn, "round": rnd}))])
        if kind == "spec_go":
            # D58 note (GH #1477, contract point 3): what a spec call's window
            # showed -- the use of its `once` notes and their receipts --, held
            # beside the turn's row; it goes to the curator only with a kept
            # answer (`spec_settle`, the verdict `kept`) and ends with the row.
            emit([lstore(put("g-put", spec_key("spec_go", session, turn),
                             canonical({"call": call, "go_ops": e.get("go_ops") or [],
                                        "sends": e.get("sends") or []})),
                         "done", call, "")])
        sys.stderr.write("lead/lead: a spec event %r it does not know -- dropped\n" % kind)
        emit([])
    if lane == "lead_note":
        n = d.get("note") if isinstance(d.get("note"), dict) else {}
        session, turn = str(n.get("session") or ""), str(n.get("turn") or "")
        kind = str(n.get("kind") or "")
        if kind == "escalated" and session:
            emit([lstore(put("n-esc", "escalated:" + session, turn), "done")])
        if kind == "errand" and session and n.get("consult_id"):
            # GH #1280: the speaking model started a consult itself -- its
            # mark, written only while none stands (a sent errand keeps its own).
            k = "consult_pending:" + session
            at = str(n.get("at") or "")
            value = canonical({"consult_id": str(n.get("consult_id")), "turn": turn, "path": "",
                               "at": at, "wait_ms": CONSULT_PENDING_MS,
                               "until": stamp_after(at, CONSULT_PENDING_MS)})
            emit([lstore([("n-cp", {"operation": "insert", "table": "state",
                                    "row": {"key": k, "value": value},
                                    "if_absent": {"key": k}})], "done")])
        if kind == "delta_end" and turn:
            # GH #1279: the delta row of a spec curate that did not reuse it.
            emit([lstore([("f-ddel", {"operation": "delete", "table": "state",
                                      "where": {"key": DELTA_KEY + turn,
                                                "value": str(n.get("raw") or "")}})], "done")])
        if kind == "spec_normal" and session and turn:
            # GH #1279: the `normal` claim goes with the call it guarded.
            emit([lstore([("f-snorm", {"operation": "delete", "table": "state",
                                       "where": {"key": spec_key("spec", session, turn),
                                                 "value": str(n.get("raw") or "")}})], "done")])
        if kind == "spec_end" and session and turn:
            # Review I-2 (GH #1407): a park beside a delegation ends the
            # turn's speculation as at a drop.
            emit([lstore([("f-pspec", {"operation": "delete", "table": "state",
                                       "where": {"key": {"in": [
                                           spec_key(k, session, turn)
                                           for k in ("spec", "spec_held", "spec_fb",
                                                     "spec_go")]}}})],
                         "done")])
        if kind == "round":
            # D58 moveout (contract point 7): a condition of the side call held
            # for a call (`when`), its sends went (held ones carry the note):
            # the turn's clock starts at its seam (`at_ms`) when the plan of
            # the verdict is this call's -- read here, written in `hz-start`.
            if not HORIZON_ADVISE or not session or not turn \
                    or not isinstance(n.get("at_ms"), int):
                emit([])
            emit([lstore([("w-plan", sel("state", ["key", "value"],
                                         {"key": {"in": [HORIZON_PLAN_KEY + session,
                                                         HORIZON_TURN_KEY + session]}}))],
                         "hz-start",
                         "", canonical({"s": session, "t": turn, "call": str(n.get("call") or ""),
                                        "at_ms": n["at_ms"]}))])
        if kind == "turn_end" and turn:
            # GH #1279: a delta row of the turn ends with it; GH #1432: a shown
            # spec sentence has done its work (an escalation keeps it).
            t_ops = []
            if DELTA_SPEC:
                t_ops.append(("t-ddel", {"operation": "delete", "table": "state",
                                         "where": {"key": DELTA_KEY + turn}}))
            if QUICK_SPECULATIVE and n.get("shown_end"):
                t_ops.append(("t-dshown", {"operation": "delete", "table": "state",
                                           "where": {"key": spec_key("spec_shown",
                                                                     session or "default",
                                                                     turn)}}))
            t_out = [lstore(t_ops, "done")] if t_ops else []
            if HORIZON_ADVISE and isinstance(n.get("round_end"), int):
                # D58 moveout (contract point 7): the answer closed the turn's
                # round (`round_end`, the curator's condition of before the
                # move) -- its duration is booked in `hz-book`.
                t_ses = session or "default"
                t_out.append(lstore([("w-turn", sel("state", ["key", "value"], {"key": {"in": [
                    HORIZON_TURN_KEY + t_ses, HORIZON_KEY]}}))], "hz-book", "",
                    canonical({"s": t_ses, "t": turn, "end": n["round_end"]})))
            emit(t_out)
        sys.stderr.write("lead/lead: a note %r it does not keep -- dropped\n" % kind)
        emit([])
    if phase == "errand":
        a = loads(str(ctx.get("cur_reason") or ""), {})
        errand = ""
        for m in d.get("messages") or []:
            if isinstance(m, dict) and str(m.get("id") or "") == "l-err":
                for r in loads(str(m.get("text") or ""), []) or []:
                    if isinstance(r, dict):
                        errand = str(r.get("value") or "")
        emit([{"header": {"route": "lead_verdict", "call": str(a.get("call") or ""),
                          "handle_ms": handle_ms()},
               "messages": [], "errand": errand, "fwd": a.get("fwd") or {}}])
    if phase == "ask":
        a = loads(str(ctx.get("cur_reason") or ""), {})
        raw = {}
        for m in d.get("messages") or []:
            if isinstance(m, dict) and str(m.get("id") or "") == "l-rows":
                for r in loads(str(m.get("text") or ""), []) or []:
                    if isinstance(r, dict):
                        raw[str(r.get("key") or "")] = str(r.get("value") or "")
        session, turn = str(a.get("session") or ""), str(a.get("turn") or "")
        call = str(a.get("call") or "")
        kept = loads(raw.get("verdict:" + session, ""), {})
        if a.get("again") and isinstance(kept, dict) and kept.get("call") == call:
            # OR-d38-3.c1.4: the policy lost its half of the join (a new
            # child) and asks again -- the verdict given, never a second one.
            v = kept.get("verdict") or {}
            emit([{"header": {"route": "lead_verdict", "call": call, "handle_ms": handle_ms()},
                   "messages": [], "verdict": v, "on": str(a.get("on") or ""),
                   "again": True}])
        state = {"escalated": raw.get("escalated:" + session, ""),
                 "consult_pending": loads(raw.get("consult_pending:" + session, ""), {}),
                 "spec": loads(raw.get(spec_key("spec", session, turn), ""), {}),
                 "spec_held": loads(raw.get(spec_key("spec_held", session, turn), ""), {}),
                 "spec_go": loads(raw.get(spec_key("spec_go", session, turn), ""), {}),
                 "called": called_other(raw.get(SPEC_CALLED_KEY + session, ""), turn, call)}
        if HORIZON_ADVISE:
            state["horizon_rounds"] = jd(raw.get(HORIZON_KEY, ""))
        st = {"path": a.get("path", ""), "needs": a.get("needs") or [],
              "families": a.get("families") or []}
        v = lead_verdict(st, a, state)
        v.update(spec_window(v, a, raw, state))
        ms = int(a.get("ask_ms") or 0) + handle_ms()
        v["handle_ms"] = ms
        # OR-d38-3.o9.4: an answer to `again` says so even when the verdict
        # was not stored yet (the ask again overtook the writes of the first):
        # a child without the legs drops it -- the first answer reads once more.
        # OR-d38-3.c1.45: `verdict:` holds a newer call of the session -- the
        # first ask's writes went then; an `again` never writes a second time.
        overwritten = bool(a.get("again") and isinstance(kept, dict) and kept.get("call"))
        emit(([] if overwritten else [lstore(lead_writes(v, a, raw), "done", call, "")]) +
             [dict({"header": {"route": "lead_verdict", "call": call, "handle_ms": ms},
                    "messages": [], "verdict": v, "on": str(a.get("on") or "")},
                   **({"again": True} if a.get("again") else {}))])
    if phase in ("spec-part", "spec-ans", "spec-await", "delta-send"):
        lg = legs(d)
        report_errors(lg)
        meta = loads(str(ctx.get("cur_reason") or ""), {})
        meta = meta if isinstance(meta, dict) else {}
        call = str(ctx.get("cur_call") or "")
        session, turn = str(meta.get("s") or ""), str(meta.get("t") or "")
        rnd = meta.get("round")
    if phase == "spec-part":
        # GH #1411 / #1415: only an `await` row of this very call whose stored
        # `needs` names no `tool` lets the partial out -- then the verdict
        # keeps the answer whatever it says. Else held back, said once.
        st = state_of(lg, "p-read")
        row = jd(st.get(spec_key("spec", session, turn), ""))
        fb = jd(st.get(spec_key("spec_fb", session, turn), ""))
        p_state = str(row.get("state") or "") or "none"
        if str(row.get("call") or "") != call and p_state != "none":
            p_state += ", call " + str(row.get("call") or "")
        elif p_state == "await" and "tool" in names_list(fb.get("needs")):
            p_state = "await, needs tool"
        elif p_state == "await":
            p_msgs = [m for m in meta.get("messages") or [] if isinstance(m, dict)]
            p_key = spec_key("spec_shown", session, turn)
            p_text = shown_text(p_msgs)
            p_first = bool(p_text and not st.get(p_key))
            # GH #1447: the first shown sentence goes to the policy as well --
            # `./intake` puts it on the wall in front of a fallback's answer
            # and reads it from the ledger (gh1432 pin 6).
            p_out = [act(call, dict({"do": "partial", "hop": meta.get("hop") or {},
                                     "messages": p_msgs},
                                    **({"shown": p_text, "s": session, "t": turn}
                                       if p_first else {})))]
            if p_first:
                # GH #1432: the first partial passed is what the rim shows;
                # first wins (`if_absent`), kept until the turn's answer.
                p_out.append(lstore([("p-shown", dict(ins("state", {
                    "key": p_key, "value": canonical({"call": call, "text": p_text})}),
                    if_absent={"key": p_key}))], "done", call, ""))
            emit(p_out)
        sys.stderr.write("lead/lead: spec partial of turn %s held back (%s)\n"
                         % (turn, p_state))
        emit([])
    if phase == "spec-ans":
        # GH #1275: a spec answer is in (`h-held`), the turn's row read after it.
        tries = int(meta.get("n") or 0)
        st = state_of(lg, "h-read")
        raw = st.get(spec_key("spec", session, turn), "")
        row = jd(raw)
        held = jd(st.get(spec_key("spec_held", session, turn), ""))
        s_state = str(row.get("state") or "")
        mine = str(row.get("call") or "") == call and str(held.get("call") or "") == call
        if mine and s_state == "held":
            # This answer holds the turn now; the normal curate decides.
            emit([])
        if mine and s_state == "await":
            fb = jd(st.get(spec_key("spec_fb", session, turn), ""))
            shown = jd(state_of(lg, "h-shown").get(spec_key("spec_shown", session, turn), ""))
            emit(spec_settle(call, session, turn, raw, row, held, fb, shown, rnd,
                             jd(st.get(spec_key("spec_go", session, turn), ""))))
        if mine and s_state == "fired" and tries < 3:
            # Held by CAS: the normal curate may move the row in between, so
            # the row is read again after the move and this phase looks again.
            nxt = dict(row, state="held") if held.get("answer") else dict(row, state="dropped")
            emit([lstore([("h-cas", upd("state", {"value": canonical(nxt)},
                                        {"key": spec_key("spec", session, turn), "value": raw})),
                          ("h-read", sel("state", ["key", "value"], {"key": {"in": [
                              spec_key(k, session, turn)
                              for k in ("spec", "spec_held", "spec_fb", "spec_go")]}})),
                          ("h-shown", sel("state", ["key", "value"],
                                          {"key": spec_key("spec_shown", session, turn)}))],
                         "spec-ans", call, canonical(dict(meta, n=tries + 1)))])
        # Dropped, released, decided without it, another call's row, or none:
        # the answer goes nowhere, and its held copy goes too.
        sys.stderr.write("lead/lead: spec answer %s of turn %s discarded (row %r)\n"
                         % (call, turn, s_state or "none"))
        ops = []
        if str(row.get("call") or "") == call and s_state in ("dropped", "released"):
            # GH #1279: the spec call's own row at its end guards nothing.
            ops.append(("h-drow", {"operation": "delete", "table": "state",
                                   "where": {"key": spec_key("spec", session, turn),
                                             "value": raw}}))
        ops.append(("h-dh", {"operation": "delete", "table": "state",
                             "where": {"key": spec_key("spec_held", session, turn),
                                       "value": st.get(spec_key("spec_held", session, turn), "")}}))
        g_raw = st.get(spec_key("spec_go", session, turn), "")
        if g_raw and str(jd(g_raw).get("call") or "") == call:
            # D58 note (GH #1477): a discarded answer books nothing it showed.
            ops.append(("h-dgo", {"operation": "delete", "table": "state",
                                  "where": {"key": spec_key("spec_go", session, turn),
                                            "value": g_raw}}))
        a = {"do": "discard", "row": row, "held": held, "s": session, "t": turn, "round": rnd,
             # A spec call that failed dropped its own row (`h-cas`): said once.
             "mark": mine and s_state == "dropped" and tries > 0 and not held.get("answer"),
             # GH #1398 (V1): the turn was decided without this answer -- late.
             "late": not raw}
        emit([lstore(ops, "done", call, "")]
             + ([act(call, a)] if a["mark"] or a["late"] else []))
    if phase == "spec-await":
        # GH #1275: the stored fallback and the move to `await`. Won: the
        # answer decides on arrival. Lost: this chain decides now.
        if (lg.get("f-sawait") or {}).get("rows_affected", 0) == 1:
            emit([])
        st = state_of(lg, "f-sread")
        raw = st.get(spec_key("spec", session, turn), "")
        row = jd(raw)
        held = jd(st.get(spec_key("spec_held", session, turn), ""))
        fb = jd(st.get(spec_key("spec_fb", session, turn), ""))
        if str(row.get("state") or "") == "held":
            emit(spec_settle(call, session, turn, raw, row, held, fb, None, rnd,
                             jd(st.get(spec_key("spec_go", session, turn), ""))))
        if str(row.get("state") or "") == "delta":
            # GH #1279: the spec curate went as the turn's call (its delta
            # stamp) -- the stored call never goes, and the row ends here.
            emit([lstore([("s-dfb", {"operation": "delete", "table": "state",
                                     "where": {"key": spec_key("spec_fb", session, turn)}}),
                          ("s-set", {"operation": "delete", "table": "state",
                                     "where": {"key": spec_key("spec", session, turn),
                                               "value": raw}})], "done", call, ""),
                  act(call, {"do": "unsent", "fb": fb, "round": rnd})])
        # Dropped without an answer (or gone): the stored call goes.
        emit([lstore([("s-dfb", {"operation": "delete", "table": "state",
                                 "where": {"key": spec_key("spec_fb", session, turn)}})],
                     "done", call, ""),
              act(call, {"do": "fb_go", "fb": fb, "round": rnd})])
    if phase == "delta-send":
        # GH #1279: the reused call of a delta stamp. The move took: it goes.
        # Lost: the turn's normal curate stored its call as the fallback of
        # this spec curate (`await`) -- that call goes, this one never went.
        st = state_of(lg, "f-dread")
        fb_key = DELTA_FB_KEY + "%s#%s" % (session, turn)
        mine = jd(st.get(fb_key, ""))
        ops = [("d-dfb", {"operation": "delete", "table": "state", "where": {"key": fb_key}})]
        a = {"do": "delta", "won": True, "mine": mine, "fb": None, "s": session, "t": turn,
             "round": rnd}
        if (lg.get("f-sdelta") or {}).get("rows_affected", 0) != 1:
            raw = st.get(spec_key("spec", session, turn), "")
            row = jd(raw)
            a["won"] = False
            a["lost"] = str(row.get("state") or "none")
            if str(row.get("state") or "") == "await" and str(row.get("call") or "") == call:
                a["fb"] = jd(st.get(spec_key("spec_fb", session, turn), ""))
                ops += [("d-set", {"operation": "delete", "table": "state",
                                   "where": {"key": spec_key("spec", session, turn),
                                             "value": raw}}),
                        ("d-sfb", {"operation": "delete", "table": "state",
                                   "where": {"key": spec_key("spec_fb", session, turn)}})]
        emit([lstore(ops, "done", call, ""), act(call, a)])
    if phase == "hz-start":
        # D58 moveout (contract point 7): the turn's clock starts when the
        # plan is the noted call's (a later call of the session wrote its
        # own plan: this one counts no more).
        lg = legs(d)
        report_errors(lg)
        meta = jd(str(ctx.get("cur_reason") or ""))
        session, turn = str(meta.get("s") or ""), str(meta.get("t") or "")
        st = state_of(lg, "w-plan")
        plan = turn_table(st.get(HORIZON_PLAN_KEY + session, "")).get(turn) or {}
        if not plan or str(plan.get("call") or "") != str(meta.get("call") or "") \
                or not isinstance(meta.get("at_ms"), int):
            emit([])
        t_key = HORIZON_TURN_KEY + session
        t_raw = st.get(t_key, "")
        emit([lstore(table_ops("w-tput", t_key, t_raw, table_put(t_raw, turn, {
            "family": str(plan.get("family") or ""), "way": str(plan.get("way") or ""),
            "seconds": plan.get("seconds"), "at_ms": meta["at_ms"]})), "done")])
    if phase == "hz-book":
        # D58 moveout (contract point 7; GH #1400 `hz-close` before the move):
        # the round of the turn ends -- its duration (seam to answer) is
        # booked under its family, what was said kept beside it; the turn's
        # row goes with the booking (compare-and-set on its value).
        lg = legs(d)
        report_errors(lg)
        meta = jd(str(ctx.get("cur_reason") or ""))
        session, turn = str(meta.get("s") or ""), str(meta.get("t") or "")
        st = state_of(lg, "w-turn")
        t_key = HORIZON_TURN_KEY + session
        t_raw = st.get(t_key, "")
        t_all = turn_table(t_raw)
        row = t_all.pop(turn, {})
        if not isinstance(row.get("at_ms"), int) or not isinstance(meta.get("end"), int) \
                or any(leg.get("error_code") for leg in lg.values()):
            emit([])
        actual = max(0, meta["end"] - row["at_ms"])
        family = str(row.get("family") or "")
        ops = table_ops("w-tdel", t_key, t_raw, t_all) \
            + put("w-rounds", HORIZON_KEY,
                  canonical(horizon_booked(jd(st.get(HORIZON_KEY, "")), family, actual)))
        if row.get("seconds") is not None:
            ops += put("w-last", HORIZON_LAST_KEY + session, canonical({
                "turn": turn, "family": family, "planned": row.get("seconds"),
                "actual": round(actual / 1000.0, 1)}))
        emit([lstore(ops, "done")])
    if phase == "ie-row":
        # D58 moveout fix round (review B M-1): the row of a real order --
        # written where none stands, in the place of a row without an order
        # (compare-and-set on the value read), never over a real order's.
        lg = legs(d)
        report_errors(lg)
        meta = jd(str(ctx.get("cur_reason") or ""))
        i_key, i_row = str(meta.get("key") or ""), meta.get("row")
        if not i_key or not isinstance(i_row, dict):
            emit([])
        i_raw = state_of(lg, "i-read").get(i_key, "")
        i_old = jd(i_raw)
        if not i_raw:
            i_op = {"operation": "insert", "table": "state",
                    "row": {"key": i_key, "value": canonical(i_row)}, "if_absent": {"key": i_key}}
        elif i_old.get("skip") or not i_old.get("live"):
            i_op = upd("state", {"value": canonical(i_row)}, {"key": i_key, "value": i_raw})
        else:
            emit([])
        emit([lstore([("i-row", i_op)], "done")])
    if phase == "done":
        emit([])
    sys.stderr.write("lead/lead: a message with no lane it serves (%r/%r) -- dropped\n"
                     % (lane, phase))
    emit([])
